/**
 * The scene service's methods, each answering the scene (the draw answers its
 * own shape), built from the class so the fake always has every method.
 */
function sceneFakes(): Record<string, jest.Mock> {
  const draw = { drawId: 1, durationSeconds: 5, sceneId: 3 };
  const names = Object.getOwnPropertyNames(ScenesService.prototype).filter(
    (name) => name !== 'constructor',
  );
  const fakes = Object.fromEntries(
    names.map((name) => [
      name,
      answers(
        name === 'findAll'
          ? [scene]
          : name === 'remove'
            ? { id: 3, name: scene.name }
            : name.startsWith('draw')
              ? draw
              : scene,
      ),
    ]),
  );
  // A neutral entry point (drawBracket, voteBracket, openBracketVoting) is a
  // thin call to the method of the same verb that carries the long name; the
  // fake does the same so both reach one mock.
  for (const wrapper of ['drawBracket', 'voteBracket', 'openBracketVoting']) {
    const target = names.find(
      (name) =>
        name !== wrapper &&
        name.startsWith(wrapper.slice(0, 4)) &&
        name.endsWith(wrapper.endsWith('Voting') ? 'Voting' : 'Bracket'),
    )!;
    fakes[wrapper] = jest.fn(
      (...args: unknown[]) => fakes[target](...args) as unknown,
    );
  }
  return fakes;
}

