  private parseSceneBackgroundFromSceneMetadata(
    sceneMetadata: unknown,
  ): { assetId: string | null; instantId: number | null } | null {
    if (sceneMetadata === null || sceneMetadata === undefined) {
      return null;
    }

    try {
      const parsed =
        typeof sceneMetadata === 'string'
          ? sceneMetadata.trim()
            ? JSON.parse(sceneMetadata)
            : null
          : sceneMetadata;
      if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
        return null;
      }
      const sceneInstant =
        'sceneInstant' in parsed
          ? (parsed as Record<string, unknown>).sceneInstant
          : null;
      if (
        !sceneInstant ||
        typeof sceneInstant !== 'object' ||
        Array.isArray(sceneInstant)
      ) {
        return null;
      }
      const assetIdRaw = (sceneInstant as Record<string, unknown>).assetId;
      const assetId =
        typeof assetIdRaw === 'string' && assetIdRaw.trim()
          ? assetIdRaw.trim()
          : null;
      const instantIdRaw = (sceneInstant as Record<string, unknown>).instantId;
      const instantIdNumeric =
        typeof instantIdRaw === 'number' ? instantIdRaw : Number(instantIdRaw);
      const instantId =
        Number.isFinite(instantIdNumeric) &&
        instantIdNumeric > 0 &&
        Number.isInteger(instantIdNumeric)
          ? instantIdNumeric
          : null;
      return assetId || instantId !== null ? { assetId, instantId } : null;
    } catch {
      return null;
    }
  }

  async takeProgramSceneInstant(
    sceneId: number | null | undefined,
    programId: string = ProgramService.DEFAULT_PROGRAM_ID,
    instantIdOverride: number | null | undefined = null,
    mediaAssetIdOverride: string | null | undefined = null,
  ) {
    const normalizedProgramId = this.normalizeProgramId(programId);
    const state = await this.prisma.programState.findUnique({
      where: { programId: normalizedProgramId },
      include: {
        activeScene: true,
        scenes: {
          include: {
            scene: true,
          },
        },
      },
    });
    if (!state) {
      throw new Error('Program not found');
    }

    const requestedSceneId =
      typeof sceneId === 'number' && Number.isFinite(sceneId)
        ? Math.round(sceneId)
        : null;
    const targetSceneId =
      requestedSceneId !== null
        ? requestedSceneId
        : (state.activeSceneId ?? null);

    if (targetSceneId === null) {
      throw new BadRequestException('No target scene selected');
    }

    const assignedSceneEntry = state.scenes.find(
      (entry) => entry.sceneId === targetSceneId,
    );
    if (!assignedSceneEntry) {
      throw new BadRequestException('Scene is not assigned to this program');
    }

    const normalizedOverrideInstantId =
      typeof instantIdOverride === 'number' &&
      Number.isFinite(instantIdOverride) &&
      Number.isInteger(instantIdOverride) &&
      instantIdOverride > 0
        ? instantIdOverride
        : null;
    const normalizedOverrideAssetId =
      typeof mediaAssetIdOverride === 'string' && mediaAssetIdOverride.trim()
        ? mediaAssetIdOverride.trim()
        : null;
    const configuredBackground = this.parseSceneBackgroundFromSceneMetadata(
      assignedSceneEntry.scene.metadata,
    );
    const hasOverride =
      normalizedOverrideAssetId !== null ||
      normalizedOverrideInstantId !== null;
    const mediaAssetId =
      normalizedOverrideAssetId ??
      (hasOverride ? null : (configuredBackground?.assetId ?? null));
    const sceneInstantId =
      normalizedOverrideInstantId ??
      (hasOverride ? null : (configuredBackground?.instantId ?? null));
    if (mediaAssetId === null && sceneInstantId === null) {
      throw new BadRequestException('Scene has no configured background audio');
    }

    let resolved: {
      instantId: number | null;
      assetId: string | null;
      name: string;
      audioUrl: string;
      volume: number;
    };
    if (mediaAssetId !== null) {
      const asset = await this.prisma.mediaAsset.findFirst({
        where: {
          id: mediaAssetId,
          enabled: true,
          backgroundAudio: { isNot: null },
        },
        include: { backgroundAudio: true, audioClip: true },
      });
      if (!asset || !asset.backgroundAudio) {
        throw new NotFoundException(
          'Configured background audio asset not found',
        );
      }
      resolved = {
        instantId: asset.audioClip?.id ?? null,
        assetId: asset.id,
        name: asset.name,
        audioUrl: asset.sourceUrl,
        volume: asset.backgroundAudio.defaultVolume,
      };
    } else {
      const instant = await this.prisma.instant.findUnique({
        where: { id: sceneInstantId! },
      });
      if (!instant) {
        throw new NotFoundException('Configured scene instant not found');
      }
      if (!instant.enabled) {
        throw new BadRequestException('Configured scene instant is disabled');
      }
      resolved = {
        instantId: instant.id,
        assetId: instant.assetId,
        name: instant.name,
        audioUrl: instant.audioUrl,
        volume: instant.volume,
      };
    }

    const nowIso = new Date().toISOString();
    const playback: ProgramSceneInstantPlayback = {
      programId: normalizedProgramId,
      sceneId: targetSceneId,
      instantId: resolved.instantId,
      mediaAssetId: resolved.assetId,
      isPlaying: true,
      instant: {
        id: resolved.instantId,
        assetId: resolved.assetId,
        name: resolved.name,
        audioUrl: resolved.audioUrl,
        volume: resolved.volume,
      },
      startedAt: nowIso,
      updatedAt: nowIso,
    };
    this.programSceneInstantPlaybackByProgramId.set(
      normalizedProgramId,
      playback,
    );

    const broadcastPayload = this.broadcastUpdate(normalizedProgramId, {
      type: 'scene_instant_take',
      sceneId: targetSceneId,
      instant: playback.instant,
      loop: true,
      triggeredAt: nowIso,
    });

    return {
      ...playback,
      version:
        broadcastPayload && typeof broadcastPayload.version === 'number'
          ? broadcastPayload.version
          : this.getProgramTopicVersion(normalizedProgramId, 'sceneInstant'),
    };
  }

  async stopProgramSceneInstant(
    programId: string = ProgramService.DEFAULT_PROGRAM_ID,
    fadeMs: number = 0,
  ) {
    const normalizedProgramId = this.normalizeProgramId(programId);
    await this.getProgramStateRecord(normalizedProgramId);

    const nowIso = new Date().toISOString();
    const previous =
      this.programSceneInstantPlaybackByProgramId.get(normalizedProgramId) ??
      this.createEmptyProgramSceneInstantPlayback(normalizedProgramId);
    const playback: ProgramSceneInstantPlayback = {
      ...previous,
      isPlaying: false,
      startedAt: null,
      updatedAt: nowIso,
    };
    this.programSceneInstantPlaybackByProgramId.set(
      normalizedProgramId,
      playback,
    );

    const broadcastPayload = this.broadcastUpdate(normalizedProgramId, {
      type: 'scene_instant_stop',
      sceneId: previous.sceneId ?? null,
      instantId: previous.instantId ?? null,
      mediaAssetId: previous.mediaAssetId ?? null,
      triggeredAt: nowIso,
      fadeMs,
    });

    return {
      ...playback,
      version:
        broadcastPayload && typeof broadcastPayload.version === 'number'
          ? broadcastPayload.version
          : this.getProgramTopicVersion(normalizedProgramId, 'sceneInstant'),
    };
  }

  /**
   * A remote audio file for the program page (the loudness envelope), under
   * the outbound-request policy: https to a public address only, GET with no
   * caller headers or cookies, audio types only, at most 100 MiB within 60 s.
   * A refusal is a 400 (the address is not allowed), 502 (the remote failed)
   * or 504 (it did not answer in time), with a plain message, never the URL.
   */
  async proxyAudio(
    url: unknown,
  ): Promise<{ buffer: Buffer; contentType: string }> {
    if (typeof url !== 'string' || !url.trim()) {
      throw new BadRequestException('url is required');
    }
    try {
      const response = await safeFetch(
        url.trim(),
        {
          path: 'program_audio',
          method: 'GET',
          maxBytes: ProgramService.PROXY_AUDIO_MAX_BYTES,
          timeoutMs: ProgramService.PROXY_AUDIO_TIMEOUT_MS,
          maxRedirects: 3,
          allowContentType: isAudioMediaType,
        },
        {
          ...this.outboundDeps,
          record: (path, result) =>
            this.metrics?.recordOutboundFetch(path, result),
        },
      );
      return { buffer: response.body, contentType: response.contentType };
    } catch (error) {
      // safeFetch only ever throws an OutboundRefusal.
      const { reason } = error as OutboundRefusal;
      const message = OUTBOUND_REFUSAL_MESSAGES[reason];
      if (reason === 'timeout') throw new GatewayTimeoutException(message);
      if (reason === 'http_status' || reason === 'network')
        throw new BadGatewayException(message);
      throw new BadRequestException(message);
    }
  }

  // Test seam: the resolver and transport the policy uses (real by default).
  outboundDeps: Omit<SafeFetchDeps, 'record'> = {};

  private static readonly PROXY_AUDIO_MAX_BYTES = 100 * 1024 * 1024;
  private static readonly PROXY_AUDIO_TIMEOUT_MS = 60_000;

  async addSceneToProgram(
    sceneId: number,
    programId: string = ProgramService.DEFAULT_PROGRAM_ID,
  ) {
    const state = await this.getProgramStateRecord(programId);
    this.assertProgramSupportsVisualConfiguration(state, 'scenes');

    const scene = await this.prisma.scene.findUnique({
      where: { id: sceneId },
    });
    if (!scene) {
      throw new Error('Scene not found');
    }

    const existing = await this.prisma.programScene.findUnique({
      where: {
        programStateId_sceneId: {
          programStateId: state.id,
          sceneId,
        },
      },
    });

    if (!existing) {
      const currentMaxPosition = await this.prisma.programScene.aggregate({
        where: { programStateId: state.id },
        _max: { position: true },
      });
      const nextPosition = (currentMaxPosition._max.position ?? -1) + 1;

      await this.prisma.programScene.create({
        data: {
          programStateId: state.id,
          sceneId,
          position: nextPosition,
        },
      });
    }

    const normalizedProgramId = this.normalizeProgramId(programId);
    const updated = await this.getProgramStateWithScenes(normalizedProgramId);
    const broadcastPayload = this.broadcastUpdate(normalizedProgramId, {
      type: 'program_scenes_changed',
      programId: normalizedProgramId,
      state: updated,
    });
    return {
      ...updated,
      version:
        broadcastPayload && typeof broadcastPayload.version === 'number'
          ? broadcastPayload.version
          : this.getProgramTopicVersion(normalizedProgramId, 'state'),
    };
  }

  async removeSceneFromProgram(
    sceneId: number,
    programId: string = ProgramService.DEFAULT_PROGRAM_ID,
  ) {
    const normalizedProgramId = this.normalizeProgramId(programId);
    const state = await this.prisma.programState.findUnique({
      where: { programId: normalizedProgramId },
      select: { id: true, activeSceneId: true, stagedSceneId: true },
    });

    if (!state) {
      throw new Error('Program not found');
    }

    await this.prisma.programScene.deleteMany({
      where: {
        programStateId: state.id,
        sceneId,
      },
    });

    const sceneInstantPlayback =
      this.programSceneInstantPlaybackByProgramId.get(normalizedProgramId);
    if (
      sceneInstantPlayback?.isPlaying &&
      sceneInstantPlayback.sceneId === sceneId
    ) {
      await this.stopProgramSceneInstant(normalizedProgramId);
    }

    if (state.activeSceneId === sceneId || state.stagedSceneId === sceneId) {
      await this.prisma.programState.update({
        where: { id: state.id },
        data: {
          ...(state.activeSceneId === sceneId ? { activeSceneId: null } : {}),
          ...(state.stagedSceneId === sceneId ? { stagedSceneId: null } : {}),
        },
      });
    }

    const updated = await this.getProgramStateWithScenes(normalizedProgramId);
    const broadcastPayload = this.broadcastUpdate(normalizedProgramId, {
      type: 'program_scenes_changed',
      programId: normalizedProgramId,
      state: updated,
    });
    return {
      ...updated,
      version:
        broadcastPayload && typeof broadcastPayload.version === 'number'
          ? broadcastPayload.version
          : this.getProgramTopicVersion(normalizedProgramId, 'state'),
    };
  }

