  async stageScene(
    sceneId: number | null,
    programId: string = ProgramService.DEFAULT_PROGRAM_ID,
  ) {
    const normalizedProgramId = this.normalizeProgramId(programId);
    const state = await this.prisma.programState.findUnique({
      where: { programId: normalizedProgramId },
      include: {
        scenes: {
          orderBy: { position: 'asc' },
          include: {
            scene: {
              include: { layout: true },
            },
          },
        },
      },
    });
    if (!state) {
      throw new Error('Program not found');
    }
    this.assertProgramSupportsVisualConfiguration(state, 'scenes');

    let nextStagedSceneId: number | null = null;
    let stagedScene: unknown = null;

    if (typeof sceneId === 'number' && Number.isFinite(sceneId)) {
      const assignedSceneEntry = state.scenes.find(
        (programScene) => programScene.sceneId === sceneId,
      );
      if (!assignedSceneEntry) {
        throw new BadRequestException('Scene is not assigned to this program');
      }
      nextStagedSceneId = sceneId;
      stagedScene = assignedSceneEntry.scene;
    }

    await this.prisma.programState.update({
      where: { id: state.id },
      data: { stagedSceneId: nextStagedSceneId },
    });

    const payload = {
      type: 'scene_staged',
      programId: normalizedProgramId,
      stagedSceneId: nextStagedSceneId,
      scene: stagedScene,
      updatedAt: new Date().toISOString(),
    };
    const broadcastPayload = this.broadcastUpdate(normalizedProgramId, payload);

    return {
      programId: normalizedProgramId,
      stagedSceneId: nextStagedSceneId,
      stagedScene: stagedScene ?? null,
      version:
        broadcastPayload && typeof broadcastPayload.version === 'number'
          ? broadcastPayload.version
          : this.getProgramTopicVersion(normalizedProgramId, 'state'),
    };
  }

  /**
   * Called by the on-air page when the countdown clock of the scene on air
   * reaches zero. That page is not signed in, so it cannot name a scene to
   * take: the target and the transition are read from the scene's own
   * settings, and nothing happens unless the scene on air has a countdown.
   */
  async completeSceneCountdown(
    programId: string = ProgramService.DEFAULT_PROGRAM_ID,
  ) {
    const state = await this.getProgramStateWithScenes(programId);
    const target = this.parseSceneCountdownTarget(state.activeScene?.metadata);
    if (!target) {
      throw new BadRequestException(
        'The scene on air has no countdown that switches scenes',
      );
    }
    return this.activateScene(target.sceneId, programId, target.transitionId);
  }

  private parseSceneCountdownTarget(
    sceneMetadata: unknown,
  ): { sceneId: number; transitionId: string } | null {
    let parsed: unknown = sceneMetadata;
    if (typeof sceneMetadata === 'string') {
      try {
        parsed = JSON.parse(sceneMetadata);
      } catch {
        return null;
      }
    }
    const clock = (parsed as Record<string, unknown> | null | undefined)?.[
      'reloj-digital-loop-clock'
    ] as Record<string, unknown> | undefined;
    if (
      !clock ||
      clock.mode !== 'countdown' ||
      !Number.isInteger(clock.countdownTargetSceneId)
    ) {
      return null;
    }
    return {
      sceneId: clock.countdownTargetSceneId as number,
      transitionId:
        typeof clock.countdownTransitionId === 'string'
          ? clock.countdownTransitionId
          : 'cut',
    };
  }

  async activateScene(
    sceneId: number,
    programId: string = ProgramService.DEFAULT_PROGRAM_ID,
    transitionId?: string | null,
  ) {
    const normalizedProgramId = this.normalizeProgramId(programId);
    const state = await this.prisma.programState.findUnique({
      where: { programId: normalizedProgramId },
      include: { scenes: true },
    });
    if (!state) {
      throw new Error('Program not found');
    }
    this.assertProgramSupportsVisualConfiguration(state, 'scenes');

    const isAssigned = state.scenes.some(
      (programScene) => programScene.sceneId === sceneId,
    );
    if (!isAssigned) {
      throw new Error('Scene is not assigned to this program');
    }

    try {
      await this.prisma.programState.update({
        where: { id: state.id },
        data: { activeSceneId: sceneId, stagedSceneId: state.activeSceneId },
      });
      this.metrics?.recordSceneHandoff('success');
    } catch (error) {
      this.metrics?.recordSceneHandoff('failure');
      throw error;
    }
    const updatedState =
      await this.getProgramStateWithScenes(normalizedProgramId);

    const normalizedTransitionId =
      typeof transitionId === 'string' && transitionId.trim()
        ? transitionId.trim()
        : null;
    const sceneBackground = updatedState.activeScene?.metadata
      ? this.parseSceneBackgroundFromSceneMetadata(
          updatedState.activeScene.metadata,
        )
      : null;
    const currentSceneInstantPlayback =
      this.programSceneInstantPlaybackByProgramId.get(normalizedProgramId);
    const shouldFadeOutPreviousSceneInstant =
      currentSceneInstantPlayback?.isPlaying &&
      currentSceneInstantPlayback.sceneId !== sceneId;

    if (sceneBackground !== null) {
      try {
        if (shouldFadeOutPreviousSceneInstant) {
          await this.stopProgramSceneInstant(normalizedProgramId, 1500);
          await new Promise<void>((resolve) => {
            setTimeout(() => resolve(), 1500);
          });
        }
        await this.takeProgramSceneInstant(sceneId, normalizedProgramId);
      } catch (err) {
        console.warn(
          `Could not play background instant for scene ${sceneId}:`,
          err instanceof Error ? err.message : err,
        );
      }
    } else {
      const sceneInstantPlayback =
        this.programSceneInstantPlaybackByProgramId.get(normalizedProgramId);
      if (
        sceneInstantPlayback?.isPlaying &&
        sceneInstantPlayback.sceneId !== sceneId
      ) {
        await this.stopProgramSceneInstant(normalizedProgramId, 1500);
      }
    }

    const broadcastPayload = this.broadcastUpdate(normalizedProgramId, {
      type: 'scene_change',
      transitionId: normalizedTransitionId,
      state: updatedState,
    });

    return {
      ...updatedState,
      version:
        broadcastPayload && typeof broadcastPayload.version === 'number'
          ? broadcastPayload.version
          : this.getProgramTopicVersion(normalizedProgramId, 'state'),
    };
  }

  async setFadeToBlack(
    active: boolean,
    programId: string = ProgramService.DEFAULT_PROGRAM_ID,
  ) {
    const normalizedProgramId = this.normalizeProgramId(programId);
    const existing = await this.prisma.programState.findUnique({
      where: { programId: normalizedProgramId },
      select: { id: true, type: true, fadeToBlack: true },
    });
    if (!existing) {
      throw new Error('Program not found');
    }
    this.assertProgramSupportsVisualConfiguration(existing, 'fade to black');

    if (existing.fadeToBlack !== active) {
      await this.prisma.programState.update({
        where: { id: existing.id },
        data: { fadeToBlack: active },
      });
    }
    const state = await this.getProgramStateWithScenes(normalizedProgramId);

    const broadcastPayload = this.broadcastUpdate(normalizedProgramId, {
      type: 'fade_to_black',
      programId: normalizedProgramId,
      active,
      state: this.withStagedSceneState(state),
      updatedAt: new Date().toISOString(),
    });

    return {
      ...this.withStagedSceneState(state),
      version:
        broadcastPayload && typeof broadcastPayload.version === 'number'
          ? broadcastPayload.version
          : this.getProgramTopicVersion(normalizedProgramId, 'state'),
    };
  }

  async takeProgramOffAir(
    programId: string = ProgramService.DEFAULT_PROGRAM_ID,
  ) {
    const normalizedProgramId = this.normalizeProgramId(programId);
    const state = await this.prisma.programState.findUnique({
      where: { programId: normalizedProgramId },
      include: { scenes: true },
    });
    if (!state) {
      throw new Error('Program not found');
    }

    if (!state.activeSceneId && !state.fadeToBlack) {
      const currentState =
        await this.getProgramStateWithScenes(normalizedProgramId);
      return {
        ...currentState,
        version: this.getProgramTopicVersion(normalizedProgramId, 'state'),
      };
    }

    await this.prisma.programState.update({
      where: { id: state.id },
      data: { activeSceneId: null, fadeToBlack: false },
    });
    const updatedState =
      await this.getProgramStateWithScenes(normalizedProgramId);

    const sceneInstantPlayback =
      this.programSceneInstantPlaybackByProgramId.get(normalizedProgramId);
    if (sceneInstantPlayback?.isPlaying) {
      await this.stopProgramSceneInstant(normalizedProgramId, 1500);
    }

    const broadcastPayload = this.broadcastUpdate(normalizedProgramId, {
      type: 'scene_change',
      transitionId: null,
      state: updatedState,
    });

    return {
      ...updatedState,
      version:
        broadcastPayload && typeof broadcastPayload.version === 'number'
          ? broadcastPayload.version
          : this.getProgramTopicVersion(normalizedProgramId, 'state'),
    };
  }

  /**
   * `flightDriven`: a stop the flight itself makes (a manual flight ending, a
   * failed timed cue, a rundown stopSong cue) stops the song but keeps the
   * rotation's mode; only operator stops halt it (#173).
   */
  takeProgramSongOffAir(
    programId: string = ProgramService.DEFAULT_PROGRAM_ID,
    options: { flightDriven?: boolean } = {},
  ) {
    return this.stopProgramSong(
      programId,
      false,
      options.flightDriven === true,
    );
  }

  stopProgramSongForTimedBlock(programId: string) {
    return this.stopProgramSong(programId, true);
  }

  private async stopProgramSong(
    programId: string,
    preserveRotation: boolean,
    flightDriven = false,
  ) {
    const normalizedProgramId = this.normalizeProgramId(programId);
    const updatedAt = new Date().toISOString();

    const currentState = await this.prisma.programState.findUnique({
      where: { programId: normalizedProgramId },
      select: { songSequence: true, audioMixer: true },
    });
    if (!currentState) {
      throw new Error('Program not found');
    }
    const currentMixerSettings = this.withResolvedProgramAudioMixerSettings(
      currentState.audioMixer,
    );

    if (
      !preserveRotation &&
      !flightDriven &&
      currentState.songSequence &&
      typeof currentState.songSequence === 'object' &&
      !Array.isArray(currentState.songSequence)
    ) {
      const updatedSequence = {
        ...(currentState.songSequence as Record<string, unknown>),
        mode: 'manual',
        activeItemId: null,
      };
      await this.prisma.programState.update({
        where: { programId: normalizedProgramId },
        data: {
          songSequence: updatedSequence as any,
        },
      });
      this.broadcastUpdate(normalizedProgramId, {
        type: 'audio_bus_update',
        programId: normalizedProgramId,
        settings: {
          songSequence: updatedSequence,
          mixerSettings: currentMixerSettings,
        },
        updatedAt,
      });
    }

    if (!preserveRotation && !flightDriven) {
      const stoppedSequence = normalizeProgramSongSequence(
        currentState.songSequence,
      );
      if (stoppedSequence)
        this.songExecutionEngine.handleSequenceUpdated(normalizedProgramId, {
          ...stoppedSequence,
          mode: 'manual',
          activeItemId: null,
        });
    }

    const stoppedPlayback = {
      token: '',
      audioUrl: '',
      progress: 0,
      currentTimeMs: 0,
      durationMs: null,
      isPlaying: false,
      updatedAt,
    };
    this.programSongPlaybackByProgramId.set(
      normalizedProgramId,
      stoppedPlayback,
    );

    this.broadcastUpdate(normalizedProgramId, {
      type: 'song_off_air',
      programId: normalizedProgramId,
      triggeredAt: updatedAt,
    });

    this.broadcastUpdate(normalizedProgramId, {
      type: 'song_playback_update',
      programId: normalizedProgramId,
      playback: stoppedPlayback,
    });

    await this.forwardStopSongToRadio(normalizedProgramId);
    console.log(
      `[ProgramService] takeProgramSongOffAir → forwarded stop to radio for ${normalizedProgramId}`,
    );
    // A timed block keeps the rotation and resumes it itself (#173).
    if (preserveRotation)
      this.songExecutionEngine.handleStopSong(normalizedProgramId, {
        keepSequence: true,
      });
    else if (flightDriven)
      this.songExecutionEngine.handleStopSong(normalizedProgramId, {
        keepMode: true,
      });
    else this.songExecutionEngine.handleStopSong(normalizedProgramId);

    return { ok: true, programId: normalizedProgramId };
  }

  async requestProgramReload(
    programId: string = ProgramService.DEFAULT_PROGRAM_ID,
  ) {
    const normalizedProgramId = this.normalizeProgramId(programId);
    await this.getProgramStateRecord(normalizedProgramId);
    const triggeredAt = new Date().toISOString();

    this.broadcastUpdate(normalizedProgramId, {
      type: 'program_reload',
      programId: normalizedProgramId,
      triggeredAt,
    });

    return {
      ok: true,
      programId: normalizedProgramId,
      triggeredAt,
    };
